# -*- coding: utf-8 -*-
# Makarychev 9, proof tasks 50–74. 875 restored from scan (n-th root). Unchanged: 64, 69.
P = {'G9_TB_ЗПТ_871': {'d': [('$x_{k} = \\dfrac{\\sqrt{a_{k+1}} - \\sqrt{a_{k}}}{d}$, поэтому сумма равна $\\dfrac{\\sqrt{a_{n+1}} - \\sqrt{a_{1}}}{d}$, а это выражение не равно $\\dfrac{n}{\\sqrt{a_{1}} + \\sqrt{a_{n+1}}}$.', 'Нужно ещё подставить $d = \\dfrac{a_{n+1} - a_{1}}{n} = \\dfrac{(\\sqrt{a_{n+1}} - \\sqrt{a_{1}})(\\sqrt{a_{n+1}} + \\sqrt{a_{1}})}{n}$; тогда выражения совпадут.'), ('Умножив на сопряжённое, получаем $x_{k} = \\sqrt{a_{k+1}} - \\sqrt{a_{k}}$, поэтому сумма равна $\\sqrt{a_{n+1}} - \\sqrt{a_{1}}$.', '$(\\sqrt{a_{k+1}} + \\sqrt{a_{k}})(\\sqrt{a_{k+1}} - \\sqrt{a_{k}}) = a_{k+1} - a_{k} = d$, поэтому $x_{k} = \\dfrac{\\sqrt{a_{k+1}} - \\sqrt{a_{k}}}{d}$.'), ('Сумма равна $\\dfrac{\\sqrt{a_{n+1}} - \\sqrt{a_{1}}}{d}$, а $a_{n+1} - a_{1} = (n + 1)d$, поэтому она равна $\\dfrac{n + 1}{\\sqrt{a_{1}} + \\sqrt{a_{n+1}}}$.', '$a_{n+1} = a_{1} + nd$, поэтому $a_{n+1} - a_{1} = nd$.')]}, 'G9_TB_ЗПТ_872': {'k': '$h_{a} = \\dfrac{2S}{a}$, $h_{b} = \\dfrac{2S}{b}$, $h_{c} = \\dfrac{2S}{c}$; если $b^{2} = ac$, то $h_{b}^{2} = \\dfrac{4S^{2}}{b^{2}} = \\dfrac{4S^{2}}{ac} = h_{a}h_{c}$, т. е. высоты образуют геометрическую прогрессию.', 'd': 'KEEP'}, 'G9_TB_ЗПТ_875': {'q': 'Докажите, что при любом натуральном значении $n > 1$ верно неравенство $\\dfrac{1}{2} < \\sqrt[n]{\\dfrac{1 \\cdot 3 \\cdot 5 \\cdot \\ldots \\cdot (2n - 1)}{2 \\cdot 4 \\cdot 6 \\cdot \\ldots \\cdot 2n}} < 1$.', 'qwhy': 'показатель корня — n, а не 3 (ошибка распознавания; с кубическим корнем левое неравенство неверно при n ≥ 21); формулировка сверена со сканом учебника (с. 212, № 875)', 'k': 'Дробь равна $\\dfrac{1}{2} \\cdot \\dfrac{3}{4} \\cdot \\ldots \\cdot \\dfrac{2n - 1}{2n}$; каждый множитель меньше $1$, а при $k \\ge 2$ множитель $\\dfrac{2k - 1}{2k} > \\dfrac{1}{2}$, поэтому при $n > 1$ имеем $\\left(\\dfrac{1}{2}\\right)^{n} < \\dfrac{1 \\cdot 3 \\cdot \\ldots \\cdot (2n - 1)}{2 \\cdot 4 \\cdot \\ldots \\cdot 2n} < 1$, и после извлечения корня $n$-й степени получаем $\\dfrac{1}{2} < \\sqrt[n]{\\ldots} < 1$.', 'd': [('Каждый множитель $\\dfrac{2k - 1}{2k} \\ge \\dfrac{1}{2}$, поэтому и произведение не меньше $\\dfrac{1}{2}$, а корень из него больше $\\dfrac{1}{2}$.', 'Произведение $n$ чисел, каждое из которых не меньше $\\dfrac{1}{2}$, не меньше $\\left(\\dfrac{1}{2}\\right)^{n}$, а не $\\dfrac{1}{2}$ (например, $\\dfrac{1}{2} \\cdot \\dfrac{3}{4} = \\dfrac{3}{8}$).'), ('При $n \\to \\infty$ дробь стремится к нулю, поэтому при больших $n$ корень меньше $\\dfrac{1}{2}$, и неравенство неверно.', 'Корень берётся $n$-й степени: из $\\left(\\dfrac{1}{2}\\right)^{n} < \\ldots$ следует $\\sqrt[n]{\\ldots} > \\dfrac{1}{2}$ при любом $n > 1$.'), ('Числитель содержит столько же множителей, сколько знаменатель, но они нечётные, а нечётные числа больше чётных, поэтому дробь больше $1$, и правое неравенство неверно.', 'Каждый множитель числителя $2k - 1$ меньше соответствующего множителя знаменателя $2k$, поэтому дробь меньше $1$.')]}, 'G9_TB_ЗПТ_881': {'k': 'При $a > 0$ имеем $a^{2} + a + 1 - 3a = (a - 1)^{2} \\ge 0$, т. е. $a^{2} + a + 1 \\ge 3a$; аналогично для $b$ и $c$. Перемножив неравенства с положительными частями и разделив на $abc > 0$, получаем, что дробь не меньше $27$.', 'd': [('$a^{2} + a + 1 \\ge a$, $b^{2} + b + 1 \\ge b$, $c^{2} + c + 1 \\ge c$, поэтому дробь не меньше $\\dfrac{abc}{abc} = 1$, а значит, и не меньше $27$.', 'Из оценки «не меньше $1$» не следует «не меньше $27$»; нужна более сильная оценка $a^{2} + a + 1 \\ge 3a$.'), ('$a^{2} + a + 1 \\ge 3a$ и т. д.; складывая, получаем $(a^{2} + a + 1) + (b^{2} + b + 1) + (c^{2} + c + 1) \\ge 3(a + b + c)$, поэтому дробь не меньше $27$.', 'Неравенства нужно перемножить (все части положительны), а не сложить: в условии произведение.'), ('При $a = b = c = 1$ дробь равна $\\dfrac{27}{1} = 27$, а при других значениях больше, поэтому неравенство верно.', 'Утверждение «при других значениях больше» и есть то, что нужно доказать.')]}, 'G9_TB_ЗПТ_883': {'k': '$1 + 10 + \\ldots + 10^{n} = \\dfrac{t - 1}{9}$, где $t = 10^{n+1}$, поэтому выражение равно $\\dfrac{(t + 5)(t - 1)}{9} + 1 = \\dfrac{t^{2} + 4t + 4}{9} = \\left(\\dfrac{t + 2}{3}\\right)^{2}$, а $t + 2 = 10^{n+1} + 2$ делится на $3$ (сумма цифр равна $3$), т. е. это квадрат натурального числа.', 'd': [('$1 + 10 + \\ldots + 10^{n} = \\dfrac{t - 1}{9}$ при $t = 10^{n+1}$, поэтому выражение равно $\\dfrac{(t + 5)(t - 1)}{9} + 1 = \\dfrac{t^{2} + 4t - 5}{9} + 1$, а это не квадрат.', '$\\dfrac{t^{2} + 4t - 5}{9} + 1 = \\dfrac{t^{2} + 4t + 4}{9} = \\left(\\dfrac{t + 2}{3}\\right)^{2}$.'), ('Выражение равно $\\left(\\dfrac{t + 2}{3}\\right)^{2}$ при $t = 10^{n+1}$, а $\\dfrac{t + 2}{3}$ — дробь, так как $10^{n+1}$ не делится на $3$, поэтому это не квадрат натурального числа.', 'Делится на $3$ не $10^{n+1}$, а $10^{n+1} + 2$: его сумма цифр равна $3$.'), ('При $n = 1$ выражение равно $(5 + 100) \\cdot 11 + 1 = 1156 = 34^{2}$, поэтому при любом $n$ оно является квадратом.', 'Проверка при одном $n$ не доказывает утверждения для всех $n$.')]}, 'G9_TB_ЗПТ_888': {'k': 'Пусть $N = a \\cdot 10^{k} + M$, где $a$ — первая цифра и $0 \\le M < 10^{k}$. Из $10M + a = 5N$ получаем $5M = a(5 \\cdot 10^{k} - 1)$; так как $5 \\cdot 10^{k} - 1$ не делится на $5$, то $a = 5$, но тогда $M = 5 \\cdot 10^{k} - 1 \\ge 10^{k}$ — противоречие.', 'd': [('Из $10M + a = 5(a \\cdot 10^{k} + M)$ получаем $5M = a(5 \\cdot 10^{k} - 1)$, и при $a = 1$ число $M = \\dfrac{5 \\cdot 10^{k} - 1}{5}$ — дробное, поэтому такого числа нет.', 'Рассмотрен только случай $a = 1$; нужно исключить все первые цифры, в том числе $a = 5$.'), ('Число $142857$ при перестановке первой цифры в конец даёт $428571 = 3 \\cdot 142857$, т. е. увеличение в $3$ раза, а не в $5$, поэтому такого числа нет.', 'Один пример не доказывает, что таких чисел нет.'), ('Из $5M = a(5 \\cdot 10^{k} - 1)$ следует $a = 5$ и $M = 5 \\cdot 10^{k} - 1$, т. е. число $N = 5 \\cdot 10^{k} + 5 \\cdot 10^{k} - 1$ существует.', '$M$ — число из $k$ цифр, т. е. $M < 10^{k}$, а $5 \\cdot 10^{k} - 1 \\ge 10^{k}$: противоречие.')]}, 'G9_TB_ЗПТ_898_a': {'k': '$4x^{2} + 4xy + y^{2} + 1 = (2x + y)^{2} + 1 \\ge 1 > 0$, поэтому левая часть не равна нулю ни при каких $x$, $y$.', 'd': [('$4x^{2} + 4xy + y^{2} + 1 = (2x + y)^{2} + 1$, и при $y = -2x$ левая часть равна нулю, поэтому решения есть.', 'При $y = -2x$ левая часть равна $1$, а не $0$.'), ('$4x^{2} + 4xy + y^{2} + 1 = (2x - y)^{2} + 1 + 8xy$, и при $xy < 0$ это может быть нулём, поэтому решения есть.', '$4x^{2} + 4xy + y^{2} = (2x + y)^{2}$; выделение квадрата выполнено неверно.'), ('При $x = 0$, $y = 1$ левая часть равна $2 \\ne 0$, поэтому решений нет.', 'Проверена одна пара чисел; нужно оценить левую часть при всех $x$, $y$.')]}, 'G9_TB_ЗПТ_898_б': {'k': '$x^{2} + y^{2} + 4x + 5 = (x + 2)^{2} + y^{2} + 1 \\ge 1 > 0$, поэтому левая часть не равна нулю ни при каких $x$, $y$.', 'd': [('$x^{2} + y^{2} + 4x + 5 = (x + 2)^{2} + y^{2} + 1$, и при $x = -2$, $y = 0$ она равна нулю, поэтому решение есть.', 'При $x = -2$, $y = 0$ левая часть равна $1$, а не $0$.'), ('$x^{2} + 4x + 5 = (x + 2)^{2} + 1$, поэтому уравнение равносильно $(x + 2)^{2} + y^{2} = -1$, и при $y^{2} = -1$ решения есть.', '$y^{2} \\ge 0$ при любом действительном $y$; сумма квадратов не может быть отрицательной.'), ('$x^{2} + y^{2} + 4x + 5 = (x + 4)^{2} + y^{2} - 11$, и при $(x + 4)^{2} + y^{2} = 11$ решения есть.', '$(x + 4)^{2} = x^{2} + 8x + 16$; верно $x^{2} + 4x = (x + 2)^{2} - 4$.')]}, 'G9_TB_ЗПТ_898_в': {'d': [('$x^{2} - 6xy + 9y^{2} + 2 = (x - 3y)^{2} + 2$, и при $x = 3y$ левая часть равна нулю, поэтому решений бесконечно много.', 'При $x = 3y$ левая часть равна $2$, а не $0$.'), ('$x^{2} - 6xy + 9y^{2} + 2 = (x - 3y)^{2} + 2$, и при $x - 3y = \\pm\\sqrt{2}$ левая часть равна нулю.', 'При $(x - 3y)^{2} = 2$ левая часть равна $4$; для нуля нужно $(x - 3y)^{2} = -2$, что невозможно.'), ('При $x = 0$, $y = 0$ левая часть равна $2 \\ne 0$, поэтому решений нет.', 'Проверена одна пара чисел; нужно оценить левую часть при всех $x$, $y$.')]}, 'G9_TB_ЗПТ_898_г': {'k': '$x^{2} + y^{2} - 2x - 4y + 6 = (x - 1)^{2} + (y - 2)^{2} + 1 \\ge 1 > 0$, поэтому левая часть не равна нулю ни при каких $x$, $y$.', 'd': [('$x^{2} + y^{2} - 2x - 4y + 6 = (x - 1)^{2} + (y - 2)^{2} + 1$, и при $x = 1$, $y = 2$ она равна нулю, поэтому решение есть.', 'При $x = 1$, $y = 2$ левая часть равна $1$, а не $0$.'), ('$x^{2} + y^{2} - 2x - 4y + 6 = (x - 1)^{2} + (y - 2)^{2} - 1$, поэтому уравнение задаёт окружность $(x - 1)^{2} + (y - 2)^{2} = 1$, и решений бесконечно много.', '$(x - 1)^{2} + (y - 2)^{2} = x^{2} + y^{2} - 2x - 4y + 5$, поэтому остаётся $+1$, а не $-1$: получается $(x - 1)^{2} + (y - 2)^{2} = -1$.'), ('При $x = 1$, $y = 0$ левая часть равна $5$, при $x = 0$, $y = 2$ равна $2$, поэтому уравнение не имеет решений.', 'Проверка отдельных пар чисел не доказывает отсутствия решений; нужно оценить левую часть при всех $x$, $y$.')]}, 'G9_TB_УПК_674_3': {'k': '$b_{n} = b_{1}q^{n-1} < 0$ при $b_{1} < 0$, $q > 1$, поэтому $b_{n+1} - b_{n} = b_{n}(q - 1) < 0$, т. е. каждый следующий член меньше предыдущего. Пример: $-2$, $-4$, $-8$, $\\ldots$ ($b_{1} = -2$, $q = 2$).', 'd': [('$b_{n+1} - b_{n} = b_{n}(q - 1) > 0$, так как $q - 1 > 0$, поэтому каждый следующий член больше. Пример: $-2$, $-4$, $-8$, $\\ldots$', '$b_{n} < 0$, поэтому произведение $b_{n}(q - 1)$ отрицательно; к тому же в примере члены убывают.'), ('$b_{n+1} = b_{n} + q < b_{n}$, так как $q > 1$. Пример: $-2$, $-4$, $-8$, $\\ldots$', 'В геометрической прогрессии $b_{n+1} = b_{n}q$, а не $b_{n} + q$; к тому же $b_{n} + q > b_{n}$.'), ('$b_{n+1} - b_{n} = b_{n}(q - 1) < 0$. Пример: $b_{1} = -2$, $q = 0{,}5$: $-2$, $-1$, $-0{,}5$, $\\ldots$', 'В примере $q = 0{,}5 < 1$, и члены возрастают; нужен пример с $q > 1$, например $-2$, $-4$, $-8$.')]}, 'G9_TB_УПК_674_4': {'q': 'Последовательность $(b_{n})$ — геометрическая прогрессия. Докажите, что если $b_{1} < 0$ и $0 < q < 1$, то каждый следующий член прогрессии больше предыдущего. Приведите пример.', 'qwhy': 'в условии был лишний латинский маркер «g)» (распознанное «г)»)', 'k': '$b_{n} = b_{1}q^{n-1} < 0$ при $b_{1} < 0$, $q > 0$, а $q - 1 < 0$, поэтому $b_{n+1} - b_{n} = b_{n}(q - 1) > 0$, т. е. каждый следующий член больше предыдущего. Пример: $-8$, $-4$, $-2$, $\\ldots$ ($q = \\dfrac{1}{2}$).', 'd': [('$b_{n+1} - b_{n} = b_{n}(q - 1) < 0$, так как $q - 1 < 0$, поэтому каждый следующий член меньше. Пример: $-8$, $-4$, $-2$, $\\ldots$', '$b_{n} < 0$ и $q - 1 < 0$, поэтому произведение положительно; к тому же в примере члены возрастают.'), ('При $0 < q < 1$ модули членов уменьшаются, поэтому и сами члены уменьшаются. Пример: $-8$, $-4$, $-2$, $\\ldots$', 'У отрицательных чисел уменьшение модуля означает увеличение самого числа: $-4 > -8$.'), ('$b_{n+1} - b_{n} = b_{n}(q - 1) > 0$. Пример: $b_{1} = -2$, $q = 2$: $-2$, $-4$, $-8$, $\\ldots$', 'В примере $q = 2 > 1$, и члены убывают; нужен пример с $0 < q < 1$.')]}, 'G9_TB_УПК_675_1': {'k': '$a_{2}a_{6} = a_{1}q \\cdot a_{1}q^{5} = a_{1}^{2}q^{6}$ и $a_{3}a_{5} = a_{1}q^{2} \\cdot a_{1}q^{4} = a_{1}^{2}q^{6}$, поэтому произведения равны.', 'd': [('$a_{2}a_{6} = a_{1}q^{2} \\cdot a_{1}q^{6} = a_{1}^{2}q^{8}$ и $a_{3}a_{5} = a_{1}q^{3} \\cdot a_{1}q^{5} = a_{1}^{2}q^{8}$, поэтому произведения равны.', '$a_{n} = a_{1}q^{n-1}$; ответ совпал, но формула $n$-го члена записана неверно.'), ('$a_{2}a_{6} = a_{1}^{2}q^{6}$ и $a_{3}a_{5} = a_{1}^{2}q^{8}$, поэтому произведения равны только при $q = 1$.', '$a_{3}a_{5} = a_{1}q^{2} \\cdot a_{1}q^{4} = a_{1}^{2}q^{6}$.'), ('$a_{2}a_{6} = a_{8}$ и $a_{3}a_{5} = a_{8}$, поэтому произведения равны.', 'Произведение членов прогрессии не равно члену с суммой номеров: $a_{2}a_{6} = a_{1}^{2}q^{6}$, а $a_{8} = a_{1}q^{7}$.')]}, 'G9_TB_УПК_675_2': {'k': '$a_{n-3}a_{n+8} = a_{1}q^{n-4} \\cdot a_{1}q^{n+7} = a_{1}^{2}q^{2n+3}$ и $a_{n}a_{n+5} = a_{1}q^{n-1} \\cdot a_{1}q^{n+4} = a_{1}^{2}q^{2n+3}$, поэтому произведения равны.', 'd': [('$a_{n-3}a_{n+8} = a_{1}^{2}q^{2n+3}$ и $a_{n}a_{n+5} = a_{1}^{2}q^{2n+4}$, поэтому произведения не равны.', '$a_{n}a_{n+5} = a_{1}q^{n-1} \\cdot a_{1}q^{n+4} = a_{1}^{2}q^{2n+3}$.'), ('$a_{n-3}a_{n+8} = a_{1}q^{n-3} \\cdot a_{1}q^{n+8} = a_{1}^{2}q^{2n+5}$ и $a_{n}a_{n+5} = a_{1}^{2}q^{2n+5}$, поэтому произведения равны.', '$a_{k} = a_{1}q^{k-1}$; ответ совпал, но формула $k$-го члена записана неверно.'), ('$a_{n-3}a_{n+8} = a_{2n+5}$ и $a_{n}a_{n+5} = a_{2n+5}$, поэтому произведения равны.', 'Произведение членов прогрессии не равно члену с суммой номеров.')]}, 'G9_TB_УПК_689_1': {'k': '$\\sqrt{\\sqrt{18} - 3} \\cdot \\sqrt{\\sqrt{18} + 3} = \\sqrt{18 - 9} = 3$, поэтому левая часть равна $\\dfrac{3}{\\sqrt{6}} = \\sqrt{\\dfrac{9}{6}} = \\sqrt{1{,}5}$.', 'd': [('$\\sqrt{\\sqrt{18} - 3} \\cdot \\sqrt{\\sqrt{18} + 3} = \\sqrt{18 + 9} = \\sqrt{27}$, поэтому левая часть равна $\\sqrt{\\dfrac{27}{6}} = \\sqrt{4{,}5}$, и равенство неверно.', '$(\\sqrt{18} - 3)(\\sqrt{18} + 3) = 18 - 9$: разность квадратов.'), ('$\\sqrt{\\sqrt{18} - 3} \\cdot \\sqrt{\\sqrt{18} + 3} = \\sqrt{18} - 3 + \\sqrt{18} + 3 = 2\\sqrt{18}$, поэтому левая часть равна $2\\sqrt{3}$, и равенство неверно.', 'Произведение корней равно корню из произведения, а не сумме подкоренных выражений.'), ('Левая часть равна $\\dfrac{3}{\\sqrt{6}} = \\dfrac{\\sqrt{6}}{2}$, а $\\sqrt{1{,}5} = \\dfrac{\\sqrt{3}}{2}$, поэтому равенство неверно.', '$\\sqrt{1{,}5} = \\sqrt{\\dfrac{6}{4}} = \\dfrac{\\sqrt{6}}{2}$.')]}, 'G9_TB_УПК_689_2': {'k': '$\\sqrt{7 + \\sqrt{24}} \\cdot \\sqrt{7 - \\sqrt{24}} = \\sqrt{49 - 24} = 5$, поэтому левая часть равна $\\dfrac{\\sqrt{10}}{5} = \\sqrt{\\dfrac{10}{25}} = \\sqrt{0{,}4}$.', 'd': 'KEEP'}, 'G9_TB_УПК_690_1': {'k': '$(\\sqrt{10} - 3)^{2} = 10 - 6\\sqrt{10} + 9 = 19 - 6\\sqrt{10}$ и $\\sqrt{10} - 3 > 0$, поэтому $\\sqrt{19 - 6\\sqrt{10}} = \\sqrt{10} - 3$.', 'd': 'KEEP'}, 'G9_TB_УПК_690_2': {'k': '$(4 - \\sqrt{7})^{2} = 16 - 8\\sqrt{7} + 7 = 23 - 8\\sqrt{7}$ и $4 - \\sqrt{7} > 0$, поэтому $\\sqrt{23 - 8\\sqrt{7}} = 4 - \\sqrt{7}$.', 'd': [('Возведём обе части в квадрат: $23 - 8\\sqrt{7} = 16 - 7 = 9$ — неверно, значит, равенство не выполняется.', '$(4 - \\sqrt{7})^{2} = 16 - 8\\sqrt{7} + 7$, а не $16 - 7$: квадрат разности — не разность квадратов.'), ('$23 - 8\\sqrt{7} = (\\sqrt{7} - 4)^{2}$, поэтому $\\sqrt{23 - 8\\sqrt{7}} = \\sqrt{7} - 4$, а это не равно $4 - \\sqrt{7}$.', '$\\sqrt{t^{2}} = |t|$, и $|\\sqrt{7} - 4| = 4 - \\sqrt{7}$, так как $\\sqrt{7} < 4$.'), ('$(4 - \\sqrt{7})^{2} = 23 - 8\\sqrt{7}$, поэтому $\\sqrt{23 - 8\\sqrt{7}} = \\pm(4 - \\sqrt{7})$, и равенство верно лишь наполовину.', 'Арифметический корень неотрицателен; так как $4 - \\sqrt{7} > 0$, корень равен именно $4 - \\sqrt{7}$.')]}, 'G9_TB_УПК_713_а': {'d': [('$a^{2} + 2a + 2 = (a + 2)^{2} - 2$, и при $a = -2$ это $-2 < 0$, поэтому выражение может быть отрицательным.', '$(a + 2)^{2} - 2 = a^{2} + 4a + 2 \\ne a^{2} + 2a + 2$; верно $(a + 1)^{2} + 1$.'), ('Дискриминант $D = 4 - 8 = -4 < 0$, поэтому выражение отрицательно при всех $a$.', 'При $D < 0$ трёхчлен сохраняет знак старшего коэффициента $1 > 0$, т. е. положителен.'), ('При $a = -1$ выражение равно $1$, при $a = 0$ равно $2$, поэтому оно не бывает отрицательным.', 'Проверка в двух точках не доказывает утверждения для всех $a$.')]}, 'G9_TB_УПК_713_б': {'k': '$2x^{2} - 2xy + y^{2} = x^{2} + (x^{2} - 2xy + y^{2}) = x^{2} + (x - y)^{2} \\ge 0$ при любых $x$, $y$.', 'd': [('$2x^{2} - 2xy + y^{2} = (x - y)^{2} \\ge 0$.', '$(x - y)^{2} = x^{2} - 2xy + y^{2}$: потеряно слагаемое $x^{2}$.'), ('$2x^{2} - 2xy + y^{2} = x^{2} + (x + y)^{2} \\ge 0$.', '$(x + y)^{2} = x^{2} + 2xy + y^{2}$: знак удвоенного произведения другой.'), ('$2x^{2} - 2xy + y^{2} = x^{2} + (x - y)^{2} - 1$, и при $x = y = 0$ оно равно $-1 < 0$.', 'Выделение квадрата не даёт слагаемого $-1$: $x^{2} + (x - y)^{2} = 2x^{2} - 2xy + y^{2}$.')]}, 'G9_TB_УПК_811_1': {'d': [('$x^{2} - 3x + 200 = (x - 3)^{2} + 191 > 0$.', '$(x - 3)^{2} = x^{2} - 6x + 9$; верно $\\left(x - \\dfrac{3}{2}\\right)^{2} + \\dfrac{791}{4}$.'), ('При $x = 0$ трёхчлен равен $200 > 0$, при $x = 1$ равен $198 > 0$, поэтому он положителен при любых $x$.', 'Проверка в двух точках не доказывает утверждения для всех $x$.'), ('Дискриминант $D = 9 - 800 < 0$, поэтому трёхчлен отрицателен при всех $x$.', 'При $D < 0$ трёхчлен сохраняет знак старшего коэффициента $1 > 0$.')]}, 'G9_TB_УПК_811_2': {'d': [('Старший коэффициент отрицателен, поэтому трёхчлен отрицателен при всех $x$.', 'Отрицательный старший коэффициент не гарантирует отрицательности: у $-x^{2} + 1$ есть положительные значения; нужно ещё $D < 0$.'), ('$-x^{2} + 22x - 125 = -(x - 11)^{2} - 4 \\ge -4$, поэтому трёхчлен может быть положительным.', '$-(x - 11)^{2} \\le 0$, поэтому $-(x - 11)^{2} - 4 \\le -4 < 0$: неравенство записано в обратную сторону.'), ('$-x^{2} + 22x - 125 = -(x - 11)^{2} + 4$, и при $x = 11$ оно равно $4 > 0$.', '$-(x - 11)^{2} = -x^{2} + 22x - 121$, поэтому свободный член $-125 + 121 = -4$.')]}, 'G9_TB_УПК_811_3': {'d': [('Дискриминант $D = 256 - 256 = 0$, поэтому трёхчлен равен нулю при всех $x$.', 'При $D = 0$ трёхчлен обращается в нуль лишь в одной точке $x = 8$.'), ('$x^{2} - 16x + 64 = (x - 8)^{2}$, и при $x < 8$ число $x - 8$ отрицательно, поэтому трёхчлен отрицателен.', 'Квадрат отрицательного числа положителен: $(x - 8)^{2} \\ge 0$ при любом $x$.'), ('$x^{2} - 16x + 64 = (x + 8)^{2} - 32x$, и при больших $x$ это отрицательно.', '$(x + 8)^{2} - 32x = x^{2} - 16x + 64 = (x - 8)^{2} \\ge 0$: слагаемое $-32x$ компенсируется ростом квадрата, и выражение не бывает отрицательным.')]}}
